 const grips=o.quad.map((_,k)=>{const g=document.createElement('div');g.className='v8quadgrip';g.textContent='';g.setAttribute('aria-label','Esquina '+(k+1));quad.append(g);return g});
 const center=document.createElement('div');center.className='v8quadmove';center.textContent='✥ Mover zona';quad.append(center);
 function paint(){polygon.setAttribute('points',o.quad.map(pt=>(pt[0]*100)+','+(pt[1]*100)).join(' '));o.quad.forEach((pt,k)=>{grips[k].style.left=(pt[0]*100)+'%';grips[k].style.top=(pt[1]*100)+'%'});const cx=o.quad.reduce((a,p)=>a+p[0],0)/4,cy=o.quad.reduce((a,p)=>a+p[1],0)/4;center.style.left=cx*100+'%';center.style.top=cy*100+'%'}paint();
 function bindGrip(target,corner){let origin=null;target.addEventListener('contextmenu',e=>e.preventDefault());target.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();snapshot();S.chosen=o.id;origin={id:e.pointerId,x:e.clientX,y:e.clientY,pts:o.quad.map(p=>[...p])};target.setPointerCapture(e.pointerId);});target.addEventListener('pointermove',e=>{if(!origin||e.pointerId!==origin.id)return;e.preventDefault();const r=$('v8canvas').getBoundingClientRect(),dx=(e.clientX-origin.x)/r.width,dy=(e.clientY-origin.y)/r.height;if(corner===-1)o.quad=origin.pts.map(p=>[Math.max(0,Math.min(1,p[0]+dx)),Math.max(0,Math.min(1,p[1]+dy))]);else o.quad[corner]=[Math.max(0,Math.min(1,origin.pts[corner][0]+dx)),Math.max(0,Math.min(1,origin.pts[corner][1]+dy))];paint()});target.addEventListener('pointerup',()=>origin=null);target.addEventListener('pointercancel',()=>origin=null)}
 grips.forEach((g,k)=>bindGrip(g,k));bindGrip(center,-1);
