$('v8link').onclick=()=>{if(!S.pages.length)return;const url=prompt('URL HTTPS del enlace (se colocará en la página activa):','https://');if(!url)return;try{const parsed=new URL(url);if(parsed.protocol!=='https:'&&parsed.protocol!=='http:')throw Error('Solo HTTP/HTTPS');addObj('link',parsed.href);const linkObj=S.objects[S.objects.length-1];if(linkObj?.type==='link'){linkObj.w=.75;linkObj.h=Math.min(.38,Math.max(.09,Math.ceil(parsed.href.length/42)*.032));linkObj.x=.1;drawObjects()}say('Enlace añadido. Puedes moverlo y cambiar su tamaño con los dedos. Guarda el PDF para crear su zona pulsable.')}catch(e){say('URL no válida: '+e.message)}};
$('v8review').onclick=async()=>{if(!S.pages.length)return;try{await libs();let blank=0,metadata=[],annotations=0;for(const [i,p] of S.pages.entries()){const d=await pdfjsLib.getDocument({data:new Uint8Array(p.bytes.slice(0))}).promise;try{const pg=await d.getPage(p.index+1),t=(await pg.getTextContent()).items.map(v=>v.str).join('').trim();if(!t&&(await pg.getOperatorList()).fnArray.length<5)blank++;annotations+=(await pg.getAnnotations()).length;if(i===0){const m=await d.getMetadata();metadata=Object.entries(m.info||{}).filter(([k,v])=>['Author','Creator','Producer','Title','Subject','Keywords'].includes(k)&&v).map(([k,v])=>k+': '+String(v).slice(0,100))}}finally{await d.destroy()}}const note=['Páginas: '+S.pages.length,'Páginas posiblemente vacías: '+blank,'Anotaciones PDF originales detectadas: '+annotations,'Elementos añadidos: '+S.objects.length,'Metadatos detectados: '+(metadata.join(' | ')||'ninguno de los habituales'),'IMPORTANTE: no garantiza detectar ni eliminar datos confidenciales, capas ocultas o información sensible.'];(()=>{const panel=$('v84reviewReport');panel.classList.remove('hidden');panel.textContent='REVISIÓN ANTES DE COMPARTIR\n\n'+note.join('\n')+'\n\nComprueba visualmente el PDF guardado antes de enviarlo.';panel.scrollIntoView({behavior:'smooth',block:'nearest'})})()}catch(e){say('No se pudo completar la revisión: '+e.message)}};


