async function rasterPDF(bytes,quality,scale){await libs();const pdf=await pdfjsLib.getDocument({data:new Uint8Array(bytes.slice(0))}).promise,flat=await PDFLib.PDFDocument.create();try{for(let k=1;k<=pdf.numPages;k++){compStatus.textContent='Rasterizando página '+k+' de '+pdf.numPages+'…';await new Promise(r=>setTimeout(r,0));const pg=await pdf.getPage(k),v=pg.getViewport({scale}),c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);if(c.width*c.height>12000000)throw Error('Página demasiado grande para rasterizar en este iPhone');await pg.render({canvasContext:c.getContext('2d'),viewport:v}).promise;const b=await new Promise((ok,no)=>c.toBlob(x=>x?ok(x):no(Error('No se pudo convertir una página')),'image/jpeg',quality));const im=await flat.embedJpg(await b.arrayBuffer()),size=pg.getViewport({scale:1});flat.addPage([size.width,size.height]).drawImage(im,{x:0,y:0,width:size.width,height:size.height});c.width=c.height=0}}finally{await pdf.destroy()}return await flat.save({useObjectStreams:true})}
function showComp(){compChoices.innerHTML='';const original=compResults[0]?.original||0;for(const x of compResults){const lab=document.createElement('label');lab.style.cssText='display:flex;gap:12px;align-items:flex-start;padding:14px;margin:8px 0;border:1px solid #dce3ee;border-radius:12px;background:#f6f8fb';const radio=document.createElement('input');radio.type='radio';radio.name='v86comp';radio.value=x.id;radio.checked=x.id===compSelected;radio.style.width='auto';radio.onchange=()=>{compSelected=x.id;compDownload.disabled=false};const desc=document.createElement('div');const delta=original?Math.round((1-x.bytes.length/original)*100):0;desc.innerHTML='<b>'+x.title+'</b><div style="margin-top:5px">'+fmt(x.bytes.length)+' · '+(delta>=0?'Ahorro '+delta+'%':'Aumenta '+Math.abs(delta)+'%')+'</div><small>'+x.description+'</small>';lab.append(radio,desc);compChoices.append(lab)}}
$('v86calc').onclick=async()=>{if(compWorking)return;if(!S.pages.length){compStatus.textContent='Añade un PDF primero.';return}compWorking=true;compDownload.disabled=true;$('v86calc').disabled=true;compResults=[];try{compStatus.textContent='Generando PDF para comparar…';const bytes=await save(false,true);if(!bytes)throw Error('No se pudo generar el PDF');const baseline=new Uint8Array(bytes);const original=baseline.length;const optimized=await PDFLib.PDFDocument.load(baseline.slice(0));const optBytes=await optimized.save({useObjectStreams:true,objectsPerTick:30});compResults=[{id:'lossless',title:'Sin pérdida',description:'PDF digital sin rasterizar.',bytes:baseline,original},{id:'balanced',title:'Optimizar estructura',description:'Reorganiza el PDF sin rasterizar; no reduce necesariamente las imágenes.',bytes:optBytes,original}];compStatus.textContent='Calculando compresión máxima…';try{const maxBytes=await rasterPDF(baseline,.55,1.0);compResults.push({id:'maximum',title:'Máxima (rasteriza)',description:'Convierte páginas a imágenes; puede perder texto, enlaces y marcadores.',bytes:maxBytes,original})}catch(e){compStatus.textContent='No se pudo calcular la opción máxima: '+e.message+'. Puedes elegir las otras dos.'}compSelected='lossless';showComp();compDownload.disabled=false;if(!compStatus.textContent.startsWith('No se pudo'))compStatus.textContent='Tamaños reales calculados. Selecciona una opción y guarda.'}catch(e){compStatus.textContent='Error al comparar: '+e.message}finally{compWorking=false;$('v86calc').disabled=false}};
compDownload.onclick=()=>{const x=compResults.find(x=>x.id===compSelected);if(!x)return;saveResult(new Blob([x.bytes],{type:'application/pdf'}),'documento_comprimido_'+x.id+'_v86.pdf');$('v8results').append(...$('results').children);say('Resultado generado: '+fmt(x.bytes.length)+'. Puedes eliminar la tarjeta de resultado sin borrar el documento original.')};
// V8.8: editor visual de campos AcroForm. Las coordenadas se guardan relativas a la página.
const formFields=[];
const formPanel=$('v87formPanel');
const formTypes={text:'Texto',date:'Fecha',checkbox:'Casilla',dropdown:'Desplegable',radio:'Selección única',signature:'Firma (texto)'};
function formRefresh(){renderFormList();drawObjects()}
function renderFormOverlays(host,page){
  for(const f of formFields.filter(f=>f.page===page.id)){
    const el=document.createElement('div');el.className='v88field';
    const paint=()=>{el.style.left=(f.x*100)+'%';el.style.top=(f.y*100)+'%';el.style.width=(f.w*100)+'%';el.style.height=(f.h*100)+'%'};
    paint();
    const label=document.createElement('div');label.className='v88fieldLabel';label.textContent=f.label;el.append(label);
    const area=document.createElement('div');area.className='v88fieldArea';
    area.textContent=f.type==='checkbox'?'☐':f.type==='radio'?'◯ '+(f.options||[]).join(' / '):f.type==='dropdown'?'Seleccionar ▾':f.type==='signature'?'Firma aquí':f.type==='date'?'DD/MM/AAAA':'Escribir aquí';
    el.append(area);
    const move=document.createElement('button');move.className='v88fieldMove';move.textContent='✥';move.type='button';move.setAttribute('aria-label','Mover campo '+f.label);el.append(move);
    function gesture(target,corner){
      let start=null;
      target.addEventListener('pointerdown',e=>{if(e.button!==0&&e.pointerType==='mouse')return;e.preventDefault();e.stopPropagation();start={id:e.pointerId,x:e.clientX,y:e.clientY,x0:f.x,y0:f.y,w:f.w,h:f.h};target.setPointerCapture(e.pointerId)});
      target.addEventListener('pointermove',e=>{if(!start||e.pointerId!==start.id)return;e.preventDefault();e.stopPropagation();const r=$('v8canvas').getBoundingClientRect();if(!r.width||!r.height)return;const dx=(e.clientX-start.x)/r.width,dy=(e.clientY-start.y)/r.height;
        if(!corner){f.x=Math.max(0,Math.min(1-f.w,start.x0+dx));f.y=Math.max(.035,Math.min(1-f.h,start.y0+dy))}
        else{let l=start.x0,t=start.y0,rr=l+start.w,bb=t+start.h;if(corner.includes('w'))l=Math.max(0,Math.min(rr-.06,l+dx));else rr=Math.min(1,Math.max(l+.06,rr+dx));if(corner.includes('n'))t=Math.max(.035,Math.min(bb-.035,t+dy));else bb=Math.min(1,Math.max(t+.035,bb+dy));f.x=l;f.y=t;f.w=rr-l;f.h=bb-t}paint()});
      const finish=e=>{if(start&&e.pointerId===start.id){start=null;renderFormList()}};
      target.addEventListener('pointerup',finish);target.addEventListener('pointercancel',finish);
    }
    gesture(move,null);
    for(const corner of ['nw','ne','se','sw']){const grip=document.createElement('button');grip.type='button';grip.className='v88fieldGrip v88'+corner;grip.setAttribute('aria-label','Ajustar esquina '+corner+' del campo '+f.label);el.append(grip);gesture(grip,corner)}
    host.append(el);
  }
}
function renderFormList(){
  const el=$('v87fieldList');el.replaceChildren();
  for(const f of formFields){
    const row=document.createElement('div');row.className='v88fieldRow';
    const label=document.createElement('span');label.textContent=f.label+' · '+formTypes[f.type];row.append(label);
    const rename=document.createElement('button');rename.type='button';rename.textContent='Renombrar';rename.onclick=()=>{const n=prompt('Texto visible encima del campo:',f.label);if(n!==null&&n.trim()){f.label=n.trim();formRefresh()}};row.append(rename);
    const del=document.createElement('button');del.type='button';del.textContent='Eliminar';del.onclick=()=>{formFields.splice(formFields.indexOf(f),1);formRefresh()};row.append(del);el.append(row);
  }
}
$('v87addField').onclick=()=>{
  if(!S.pages.length){say('Añade primero un PDF.');return}
  const type=$('v87fieldType').value,label=$('v87fieldName').value.trim()||('Campo '+(formFields.length+1));
  const options=$('v87fieldOptions').value.split(',').map(x=>x.trim()).filter(Boolean);
  const n=formFields.length+1;
  formFields.push({page:S.pages[S.active].id,type,name:'orlando_'+n+'_'+label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_]/g,'_'),label,x:.16,y:Math.min(.78,.22+(n%5)*.105),w:.66,h:.065,options:options.length?options:['Sí','No']});
  formRefresh();$('v83edit').click();
  $('v83viewport').scrollIntoView({behavior:'smooth',block:'center'});
  say('Campo insertado en la página. Arrastra ✥ para moverlo y las cuatro esquinas para cambiar su tamaño.');
};
