$('v8crop').onclick=async()=>{if(!S.pages.length)return;const n=prompt('Porcentaje de margen a recortar en los cuatro lados (0-25):','5');if(n===null)return;const m=Number(n);if(!Number.isFinite(m)||m<0||m>25){say('Margen no válido.');return}snapshot();const chosen=S.pages.filter(p=>S.selected.has(p.id));for(const p of (chosen.length?chosen:[S.pages[S.active]])){p.crop=m/100}say('Recorte visual aplicado. Comprueba el resultado al exportar.');await view()};
