$('v8search').onclick=async()=>{const q=prompt('Palabra o frase a buscar:');if(!q)return;try{await libs();let found=[];for(let i=0;i<S.pages.length;i++){const p=S.pages[i],doc=await pdfjsLib.getDocument({data:new Uint8Array(p.bytes.slice(0))}).promise;const pg=await doc.getPage(p.index+1),t=(await pg.getTextContent()).items.map(x=>x.str).join(' ');if(t.toLocaleLowerCase().includes(q.toLocaleLowerCase()))found.push(i+1);await doc.destroy()}say(found.length?'Coincidencias en páginas: '+found.join(', '):'No se encontraron coincidencias en el texto digital. Un escaneado requiere OCR.');if(found.length){S.active=found[0]-1;await view()}}catch(e){say('Error al buscar: '+e.message)}};
// V8.8.2: controles conectados y biblioteca local.
function requirePage(){if(!S.pages.length){say('Primero añade un PDF.');return false}return true}
$('v8highlight').onclick=()=>{if(!requirePage())return;document.dispatchEvent(new CustomEvent('orlando-ink-start'));$('v83viewport').scrollIntoView({behavior:'smooth',block:'center'});say('Resaltador activado. Desliza un dedo sobre la página; dos dedos para ampliar.')};
document.addEventListener('orlando-ink-stroke',e=>{if(!S.pages.length)return;const d=e.detail;if(!d.points?.length)return;snapshot();S.objects.push({id:Math.random().toString(36).slice(2),page:S.pages[S.active].id,type:'ink',points:d.points,rgb:d.rgb,size:d.size});document.dispatchEvent(new CustomEvent('orlando-page-changed',{detail:{id:S.pages[S.active].id,objects:S.objects.filter(o=>o.page===S.pages[S.active].id&&o.type==='ink')}}));say('Resaltado añadido. Guarda el PDF para exportarlo.')});
